  let slope=null;if(ins.length>=3){const n=ins.length,xs=ins.map((_,k)=>k),ys=ins.map(o=>o.v);const mx=_avg(xs),my=_avg(ys);slope=xs.reduce((s,x,k)=>s+(x-mx)*(ys[k]-my),0)/xs.reduce((s,x)=>s+(x-mx)**2,0)}
