const projM=a=>a?(a.projetos=a.projetos||{}):{};
function projetoDe(t,a){a=a||A();if(!t||!a)return '';const v=projM(a)[normTurma(t.nome)];if(v!=null)return v;const c=t.mraCfg&&t.mraCfg.projeto;if(c)return c;try{const d=_mraDef&&mraCursoDef(t);if(d&&d.projeto)return d.projeto}catch(_){}return ''}
