function setProjeto(a,nome,v){if(!a||!nome)return;const k=normTurma(nome);v=String(v||'').trim();if(v)projM(a)[k]=v;else delete projM(a)[k];a.turmas.forEach(t=>{if(normTurma(t.nome)===k&&t.mraCfg)delete t.mraCfg.projeto});save()}
