function setTurmaDado(a,nome,k,v){if(!a||!nome)return;const key=normTurma(nome);const o=turmaDM(a)[key]=turmaDM(a)[key]||{};o[k]=String(v||'').trim();save()}
document.addEventListener('change',e=>{const el=e.target;if(!el)return;const map={'et-cfich':'cursoFicha','et-ori':'orientador','et-gen':'genero'};if(map[el.id]){const n=($('#et-nome')||{}).value;setTurmaDado(A(),n,map[el.id],el.value);toast('Guardado nos dados da turma '+n,'ok')}},true);
