{const _md=mraDados;mraDados=function(t,m){const D=_md.apply(this,arguments);try{const c=D.cursos[0];const nome=turmaDado(t,'cursoFicha')||c.nome;if(nome!==c.nome){D.cursos=D.cursos.filter(x=>x.nome!==nome);c.nome=nome}c.orientador=turmaDado(t,'orientador')||c.orientador;c.genero=turmaDado(t,'genero')||c.genero||'F';c.projeto=projetoDe(t)}catch(e){console.warn(e)}return D}}
