/* seletor de turma da barra: disciplinas longas abreviadas (o nome completo fica na dica) */
function abrevDisc(n){n=String(n||'');if(n.length<=18)return n;const sg=n.split(/\s[-–]\s/);if(sg.length>1&&sg[sg.length-1].length<=18)return sg[sg.length-1].trim();const w=n.replace(/[()]/g,'').split(/[\s\-–]+/).filter(x=>x&&!/^(da|de|do|das|dos|e|a|o|em|para|na|no)$/i.test(x));const s=w.map(x=>/^[IVX]+$/.test(x)?x:x[0].toUpperCase()).join('');return s.length>=2&&s.length<=6?s:n.slice(0,16)+'…'}
{const _fc=fillCtx;fillCtx=function(){const r=_fc.apply(this,arguments);try{const st=$('#selTurma');const a=A();if(st&&a)[...st.options].forEach(o=>{const t=a.turmas.find(x=>x.id===o.value);if(t&&t.disciplina&&t.disciplina.length>18){o.textContent=t.nome+' · '+abrevDisc(t.disciplina);o.title=t.nome+' · '+t.disciplina}});if(st){const t=T();st.title=t?t.nome+' · '+t.disciplina:''}}catch(_){}return r}}


